# Sign with the existing enterprise publisher; run elevated on DC01.
[CmdletBinding()]
param()
$ErrorActionPreference='Stop'
$script:awOldHash='4c1b14a1c088b0ac28f63337ff681824da560d6bf9143bf79132720850f2067d'
$script:awNewHash='faec4a852f61528b8e8df9ab6240323ab4cedae497cadd921568ccf06dac3609'
$script:awTemplate=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
$script:awAudit=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
. ([scriptblock]::Create($script:awAudit))
function Test-AwPilotPackage($Directory,$Hash,$Publisher,$Root) {
    . ([scriptblock]::Create($script:awAudit.Replace($script:awNewHash,$Hash)))
    $r=Invoke-AuthWireGpoAudit -Directory $Directory -OnlyPackage -Url 'https://kaname.vizyonveri.local:8765' -Domain 'vizyonveri.local' -RootThumbprint $Root
    if(!$r.PackageChecksPassed) {throw ('Package audit failed: '+(($r.PackageChecks.GetEnumerator()|Where-Object {!$_.Value}|ForEach-Object Key)-join ','))}
    if($r.Startup.InstallEntryCount -ne 1 -or !$r.Startup.ExplicitAllSigned -or $r.Startup.BypassReferenced) {throw 'Exactly one AllSigned Startup call is required.'}
    if(@($r.Scripts|Where-Object {$_.PublisherThumbprint -ine $Publisher}).Count) {throw 'Existing publisher differs.'}
}
function Get-AwPackageSnapshot($Directory) {
    $result=[ordered]@{}; $parent=Split-Path $Directory -Parent
    $items=@((Get-Item $parent),(Get-Item $Directory))+@(Get-ChildItem $Directory -Force -Recurse)+@(Get-ChildItem $parent -File -Force)
    foreach($item in ($items|Sort-Object FullName)) {
        if($item.Attributes -band [IO.FileAttributes]::ReparsePoint) {throw 'Package links refused.'}
        $hash=if($item.PSIsContainer){''}else{(Get-FileHash -LiteralPath $item.FullName).Hash}
        $result[$item.FullName.Substring($parent.Length)]=[pscustomobject]@{Hash=$hash;Sddl=(Get-Acl -LiteralPath $item.FullName).Sddl}
    }; return $result
}
function Assert-AwPackagePreserved($Before,$After,[switch]$IncludeInstaller) {
    if(($Before.Keys-join '|') -cne ($After.Keys-join '|')) {throw 'Package file set changed.'}
    foreach($key in $Before.Keys) {
        if($Before[$key].Sddl -cne $After[$key].Sddl) {throw ('Permissions changed: '+$key+' before='+$Before[$key].Sddl+' after='+$After[$key].Sddl)}
        if(!$IncludeInstaller -and $key -ieq '\Startup\Install-AuthWire.ps1') {continue}
        if($Before[$key].Hash -cne $After[$key].Hash) {throw ('Protected file changed: '+$key)}
    }
}
function Update-AwPilotInstaller($Directory,$Certificate,$BackupDirectory,$Root) {
    if(!$Certificate.HasPrivateKey -or $Certificate.NotAfter -le (Get-Date) -or $Certificate.NotBefore -gt (Get-Date)) {throw 'Current signing private key unavailable.'}
    $target=Join-Path $Directory 'Install-AuthWire.ps1'; $text=[IO.File]::ReadAllText($target)
    $current=Get-AuthWireBodyHash -Text $text -Installer
    if($current -notin @($script:awOldHash,$script:awNewHash)) {throw 'Unexpected existing installer body.'}
    Test-AwPilotPackage $Directory $current $Certificate.Thumbprint $Root
    if($current -eq $script:awNewHash) {return [pscustomobject]@{event='SYSVOL_INSTALLER_UPDATED';verified=$true;updated=$false;already_current=$true;vv06_boot_acceptance_pending=$true}}
    $before=Get-AwPackageSnapshot $Directory
    $oldBytes=[IO.File]::ReadAllBytes($target); $oldAcl=Get-Acl -LiteralPath $target
    if(Test-Path -LiteralPath $BackupDirectory) {throw 'Backup destination already exists.'}
    $null=New-Item -ItemType Directory -Path $BackupDirectory
    $acl=New-Object Security.AccessControl.DirectorySecurity; $acl.SetAccessRuleProtection($true,$false)
    $acl.SetOwner((New-Object Security.Principal.SecurityIdentifier('S-1-5-32-544')))
    foreach($sid in @('S-1-5-18','S-1-5-32-544')) {$acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule((New-Object Security.Principal.SecurityIdentifier($sid)),'FullControl','ContainerInherit,ObjectInherit','None','Allow')))}
    Set-Acl -LiteralPath $BackupDirectory -AclObject $acl
    [IO.File]::WriteAllBytes((Join-Path $BackupDirectory 'Install-AuthWire.before.ps1'),$oldBytes)
    $before|ConvertTo-Json -Depth 5|Set-Content (Join-Path $BackupDirectory 'manifest-before.json') -Encoding UTF8
    $candidate=Join-Path $BackupDirectory 'Install-AuthWire.candidate.ps1'
    $installed=$false; $replacementHash=''
    try {
        $lf=[string][char]10; $normalized=$text.TrimStart([char]0xfeff).Replace(([string][char]13+[char]10),$lf).Replace([string][char]13,$lf)
        $map=[regex]::Match($normalized,'(?s)\$expectedAssets\s*=\s*@''\n(?<payload>.*?)\n''@\s*\|\s*ConvertFrom-Json').Groups['payload'].Value
        if(!$map -or (Get-AuthWireBodyHash -Text $script:awTemplate -Installer) -cne $script:awNewHash) {throw 'Pinned candidate template invalid.'}
        [IO.File]::WriteAllText($candidate,$script:awTemplate.Replace('__AUTHWIRE_ASSET_HASHES__',$map),(New-Object Text.UTF8Encoding($true)))
        $signed=Set-AuthenticodeSignature -FilePath $candidate -Certificate $Certificate -HashAlgorithm SHA256
        if($signed.Status -ne 'Valid' -or $signed.SignerCertificate.Thumbprint -ine $Certificate.Thumbprint) {throw 'Candidate signature invalid.'}
        if((Get-AuthWireBodyHash -Text ([IO.File]::ReadAllText($candidate)) -Installer) -cne $script:awNewHash) {throw 'Signed candidate body changed.'}
        $replacementHash=(Get-FileHash -LiteralPath $candidate).Hash
        Assert-AwPackagePreserved $before (Get-AwPackageSnapshot $Directory) -IncludeInstaller
        # Atomic replacement preserves the existing destination security descriptor.
        [IO.File]::Replace($candidate,$target,[NullString]::Value); $installed=$true
        Set-Acl -LiteralPath $target -AclObject $oldAcl
        if((Get-FileHash -LiteralPath $target).Hash -cne $replacementHash) {throw 'Installed bytes differ.'}
        Test-AwPilotPackage $Directory $script:awNewHash $Certificate.Thumbprint $Root
        Assert-AwPackagePreserved $before (Get-AwPackageSnapshot $Directory)
        $result=[pscustomobject]@{event='SYSVOL_INSTALLER_UPDATED';verified=$true;updated=$true;backup=$BackupDirectory;publisher=$Certificate.Thumbprint;installer_body_sha256=$script:awNewHash;installer_sha256=$replacementHash;client_and_assets_preserved=$true;startup_entries=1;all_signed=$true;package_permissions_preserved=$true;gpo_settings_changed=$false;windows_task_changed=$false;vv06_boot_acceptance_pending=$true}
        $result|ConvertTo-Json -Depth 5|Set-Content (Join-Path $BackupDirectory 'result.json') -Encoding UTF8
        return $result
    } catch {
        $failure=$_
        if($installed) {
            if((Get-FileHash -LiteralPath $target).Hash -cne $replacementHash) {throw 'External installer change; rollback refused. Retain backup.'}
            $rollback=Join-Path $BackupDirectory 'Install-AuthWire.rollback.ps1'; [IO.File]::WriteAllBytes($rollback,$oldBytes)
            [IO.File]::Replace($rollback,$target,[NullString]::Value); Set-Acl -LiteralPath $target -AclObject $oldAcl
            Assert-AwPackagePreserved $before (Get-AwPackageSnapshot $Directory) -IncludeInstaller
            Write-Output '{"event":"SYSVOL_INSTALLER_ROLLED_BACK","verified":true}'
        }; throw $failure
    }
}
if($MyInvocation.InvocationName -ne '.') {
    try {
        if($env:COMPUTERNAME -ine 'DC01') {throw 'Run only on DC01.'}
        $identity=[Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()
        if(!$identity.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {throw 'Elevated PowerShell is required.'}
        $computer=Get-CimInstance Win32_ComputerSystem
        if($computer.DomainRole -lt 4 -or $computer.Domain -ine 'vizyonveri.local') {throw 'Expected domain controller unavailable.'}
        Import-Module GroupPolicy
        $gpo=Get-GPO -Guid 'e5a9ab39-3709-49cb-837a-0208d2eb3b12' -Domain 'vizyonveri.local'
        if($gpo.DisplayName -cne 'AuthWire-Pilot-Trust' -or $gpo.GpoStatus.ToString() -ne 'AllSettingsEnabled') {throw 'Unexpected pilot GPO.'}
        $apply=@(Get-GPPermission -Guid $gpo.Id -All -Domain 'vizyonveri.local'|Where-Object Permission -eq 'GpoApply'|ForEach-Object {$_.Trustee.Name})
        if($apply.Count -ne 1 -or $apply[0] -cne 'AuthWire-Pilot-Computers') {throw 'Pilot filtering differs.'}
        $signers=@(Get-ChildItem Cert:\CurrentUser\My,Cert:\LocalMachine\My|Where-Object {$_.Thumbprint -ieq '6E74B513F766E01730719684A41B2664380CA68A' -and $_.HasPrivateKey})
        if(!$signers.Count) {throw 'Existing enterprise signing key not found.'}
        $directory=Join-Path $env:SystemRoot 'SYSVOL\sysvol\vizyonveri.local\Policies\{e5a9ab39-3709-49cb-837a-0208d2eb3b12}\Machine\Scripts\Startup'
        $backup=Join-Path $env:ProgramData ('AuthWire-Admin-Backup-'+(Get-Date -Format 'yyyyMMdd-HHmmss')+'-'+[guid]::NewGuid().ToString('N'))
        Update-AwPilotInstaller $directory $signers[0] $backup 'C789A0595ADB95A6BE4534D01B1D205F6C37DE18'|ConvertTo-Json -Depth 5
    } catch {[pscustomobject]@{event='SYSVOL_INSTALLER_UPDATE_FAILED';error=$_.Exception.Message;vv06_boot_acceptance_pending=$true}|ConvertTo-Json;exit 1}
}
